const msg = $input.item.json;
const text = msg.text || '';
const files = msg.files || [];
const driveMatch = text.match(/https:\/\/(?:drive|docs)\.google\.com\/[^\s<>"]+/);
const hasFile = files.length > 0;
if (!driveMatch && !hasFile) return [];
let docUrl = '', docName = '', docType = 'Other';
if (hasFile) {
  const file = files[0];
  docName = file.name || file.title || 'Untitled';
  docUrl = file.permalink || file.url_private || '';
  const n = docName.toLowerCase();
  if (n.includes('proposal')) docType = 'Proposal';
  else if (n.includes('contract') || n.includes('sow')) docType = 'Contract';
  else if (n.includes('deck') || n.includes('slide') || n.endsWith('.pptx')) docType = 'Deck';
  else if (n.includes('brief')) docType = 'Brief';
} else {
  docUrl = driveMatch[0];
  const u = docUrl.toLowerCase();
  if (u.includes('presentation')) docType = 'Deck';
  else if (u.includes('proposal')) docType = 'Proposal';
  const pathPart = docUrl.replace(/https:\/\/[^/]+\//, '').split('/')[0];
  docName = 'Drive: ' + pathPart.charAt(0).toUpperCase() + pathPart.slice(1);
}
const senderName = msg.username || (msg.user_profile && msg.user_profile.display_name) || msg.user || '';
const channelName = msg.channel_name || msg.channel || '';
const date = msg.ts ? new Date(parseFloat(msg.ts) * 1000).toISOString().split('T')[0] : '';
return [{ json: { docName, docUrl, docType, channelId: msg.channel, channelName, senderName, date } }];
